assert.throws(() => findConflicts([t('2026-03-01T10:00:00z','2026-03-01T11:00:00Z')]), TypeError);
assert.throws(() => findConflicts([t('2026-03-01T10:00:00Z','2026-03-01T11:00:00Z+01:00')]), TypeError);
assert.throws(() => findConflicts([t('2026-03-01T10:00:00.000Z','2026-03-01T11:00:00Z')]), TypeError);
assert.throws(() => findConflicts([{ id: '', room: 'R', start: '2026-03-01T10:00:00Z', end: '2026-03-01T11:00:00Z' }]), TypeError);
assert.throws(() => findConflicts([{ id: 'x', room: '', start: '2026-03-01T10:00:00Z', end: '2026-03-01T11:00:00Z' }]), TypeError);
assert.throws(() => findConflicts([{ id: 1, room: 'R', start: '2026-03-01T10:00:00Z', end: '2026-03-01T11:00:00Z' }]), TypeError);
assert.throws(() => findConflicts('nope'), TypeError);
assert.throws(() => findConflicts([null]), TypeError);
assert.throws(() => findConflicts([42]), TypeError);

// R2: end not after start
assert.throws(() => findConflicts([t('2026-03-01T10:00:00Z','2026-03-01T10:00:00Z')]), RangeError);
assert.throws(() => findConflicts([t('2026-03-01T11:00:00Z','2026-03-01T10:00:00Z')]), RangeError);

