assert.throws(() => findConflicts([t('2026-03-01T10:00:00Z','2026-03-01T11:00:00Z','a'), t('2026-03-01T10:00:00Z','2026-03-01T11:00:00Z','a')]), TypeError);
// booking 1 has bad end (RangeError) AND later booking would dup its id: range error first
assert.throws(() => findConflicts([t('2026-03-01T11:00:00Z','2026-03-01T10:00:00Z','a'), t('2026-03-01T10:00:00Z','2026-03-01T11:00:00Z','a')]), RangeError);
