assert.deepEqual(findConflicts([t(S,E,'a'), t(S,M,'b')]), [['a','b']]);       // containment
assert.deepEqual(findConflicts([t(S,E,'a'), t(S,E,'b')]), [['a','b']]);       // identical
assert.deepEqual(findConflicts([t(S,M,'a','A1'), t(S,M,'b','a1')]), []);      // case-sensitive rooms
assert.deepEqual(findConflicts([t(S,M,'a','A1'), t(S,M,'b','A1')]), [['a','b']]);

